import { Component } from '@angular/core';
import { SurveyService } from 'src/app/service/survey.service';

@Component({
  selector: 'app-admin-page',
  templateUrl: './admin-page.component.html',
  styleUrls: ['./admin-page.component.css'],
  standalone: false
})
export class AdminPageComponent {
     constructor(private surveyService: SurveyService) {}
     survey = this.surveyService.getAll()
     data: any[] = [];

     ngOnInit() {
      this.survey.subscribe((data) =>
          this.data = data
       )
     }
     post() {
        console.log("My post is working")
    }

    delete(id: number){ {
      // console.log(this.data.id)
      this.surveyService.delete(id)
    }}

    edit(){
      console.log("My edit is working")
    }
}
<div class="admin">
  <div class="reroute-btns">
    <button class="admin-result-btn" routerLink="/results">Results</button>
  </div>

  <div class="create-btn-div">
    <button class="create-survey-btn" routerLink="/create-survey">Create Survey</button>
  </div>

  <div class="admin-surveys-div">
    <div class="admin-survey-div" *ngFor="let data of data">
      <div class="admin-survey-data-div">
        <h1 class="admin-survey-title">{{data.title}}</h1>
        <h2 class="admin-survey-desc"><span class="divider">|</span>{{data.desc}}</h2>
        <span class="divider">|</span>
      </div>
      <div class="admin-survey-action-btn">
        <button class="admin-survey-post-btn" (click)="post()">Post</button>
        <button class="admin-survey-edit-btn" (click)="edit()">Edit</button>
        <button class="admin-survey-delete-btn" (click)="delete(data.id)">Delete</button>
      </div>
    </div>
  </div>
</div>
